export type SubscriptionPlanInput = { "billing_interval": "daily" | "weekly" | "monthly" | "yearly"; /** Format: int32. */ "billing_interval_count": number; /** maxItems: 12. */ "billing_interval_options": Array<SubscriptionIntervalOptionInput>; /** Format: int32. */ "contract_term_months"?: number; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: never; /** ISO 4217 currency code. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; "delivery_method_subscription_counts"?: never; "delivery_required"?: never; "description"?: string; "early_termination_fee_money"?: MoneyValueInput; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "images": Array<ImageInput>; /** Where tracked demand from this plan is routed. New subscriptions and payment links for the plan copy it. Absent when the plan has no source. */ "inventory_routing_source"?: InventoryRoutingSourceRequestInput; "line_items"?: Array<SubscriptionPlanLineItemInput>; "merchant_id"?: never; "metadata"?: Record<string, string>; "name": string; /** maxItems: 10. */ "quantity_options": Array<number>; "setup_fee_money"?: MoneyValueInput; "status"?: never; "subscription_delivery_method_ids": Array<string>; "subscription_plan_id"?: never; /** Format: int32. */ "trial_period_days"?: number; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: never; /** Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "version"?: never; };
